import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p89_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor cumsum_lastdim_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cumsum_lastdim", &cumsum_lastdim_cuda, "Contiguous last-dim cumsum (CUDA float32)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256

__device__ __forceinline__ float warp_inclusive_scan(float val) {
    for (int offset = 1; offset < 32; offset <<= 1) {
        float n = __shfl_up_sync(0xffffffff, val, offset);
        if ((threadIdx.x & 31) >= offset) val += n;
    }
    return val;
}

__global__ void cumsum_lastdim_kernel(const float* __restrict__ input,
                                       float* __restrict__ output,
                                       int cols) {
    extern __shared__ float warp_sums[];
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int num_warps = (BLOCK_SIZE + 31) / 32;
    int warp_id = tid >> 5;
    int lane = tid & 31;

    const float* row_in = input + (long long)row * cols;
    float* row_out = output + (long long)row * cols;

    // Each thread accumulates a local running sum over its strided elements
    // We do a two-pass approach:
    // Pass 1: each thread computes partial sum for its elements
    // Then we do a block-level inclusive scan of per-thread totals
    // Pass 2: each thread adds its prefix and writes outputs

    // Compute per-thread total
    float local_total = 0.0f;
    for (int i = tid; i < cols; i += BLOCK_SIZE) {
        local_total += row_in[i];
    }

    // Warp-level inclusive scan of local_total
    float warp_scan = warp_inclusive_scan(local_total);

    // Store warp totals (last lane of each warp)
    if (lane == 31 || tid == BLOCK_SIZE - 1) {
        warp_sums[warp_id] = warp_scan;
    }
    __syncthreads();

    // First warp scans warp_sums
    if (warp_id == 0 && lane < num_warps) {
        float v = warp_sums[lane];
        for (int offset = 1; offset < 32; offset <<= 1) {
            float n = __shfl_up_sync(0xffffffff, v, offset);
            if (lane >= offset) v += n;
        }
        warp_sums[lane] = v;
    }
    __syncthreads();

    // Each thread's prefix = sum of all warp totals before its warp
    // + exclusive prefix within its warp
    float block_prefix = (warp_id > 0) ? warp_sums[warp_id - 1] : 0.0f;
    // exclusive warp prefix for this thread = warp_scan - local_total
    float thread_prefix = block_prefix + (warp_scan - local_total);

    // Pass 2: write outputs with running sum
    float running = thread_prefix;
    for (int i = tid; i < cols; i += BLOCK_SIZE) {
        running += row_in[i];
        row_out[i] = running;
    }
}

torch::Tensor cumsum_lastdim_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.dim() >= 1, "Input must have at least 1 dimension");

    auto output = torch::empty_like(x);
    int cols = x.size(-1);
    long long rows = x.numel() / cols;

    if (rows == 0 || cols == 0) return output;

    int num_warps = (BLOCK_SIZE + 31) / 32;
    size_t shared_mem = num_warps * sizeof(float);

    cumsum_lastdim_kernel<<<(int)rows, BLOCK_SIZE, shared_mem>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        cols
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A simple model that performs a cumulative sum (prefix sum) operation along a specified dimension.

        Parameters:
            dim (int): The dimension along which to perform the scan operation.
        """
    def __init__(self, dim):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initialize the Scan model.

                Args:
                    dim (int): The dimension along which to perform the cumulative sum.
                """
        self.dim = dim
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        int ndim = x.dim();
        int dim = (self.dim >= 0) ? self.dim : self.dim + ndim;
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if (x.is_cuda && x.dtype == torch::kFloat32 && x.is_contiguous() && ndim >= 1 && dim == ndim - 1) {
            return _stark_get_extension().cumsum_lastdim(x);
        }
        return torch.cumsum(x, dim=self.dim);
        # <<<END_IMPROVE>>>

