CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Warp-level inclusive scan using shuffle
__device__ __forceinline__ float warp_inclusive_scan(float val) {
    for (int offset = 1; offset < 32; offset <<= 1) {
        float n = __shfl_up_sync(0xffffffff, val, offset);
        if ((threadIdx.x & 31) >= offset) val += n;
    }
    return val;
}

// Kernel for short rows: one warp per row, cols <= 32
__global__ void cumsum_warp_kernel(const float* __restrict__ input,
                                    float* __restrict__ output,
                                    int cols,
                                    long long rows) {
    long long row = (long long)blockIdx.x * blockDim.y + threadIdx.y;
    if (row >= rows) return;
    int lane = threadIdx.x;
    float val = (lane < cols) ? input[row * cols + lane] : 0.0f;
    val = warp_inclusive_scan(val);
    if (lane < cols) output[row * cols + lane] = val;
}

// Kernel for longer rows: one block per row, block-level hierarchical scan
// Each thread handles multiple elements in a strided fashion
#define BLOCK_SCAN_THREADS 256

__global__ void cumsum_block_kernel(const float* __restrict__ input,
                                     float* __restrict__ output,
                                     int cols) {
    extern __shared__ float smem[]; // size = num_warps floats
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int num_warps = (BLOCK_SCAN_THREADS + 31) / 32;
    int warp_id = tid >> 5;
    int lane = tid & 31;

    const float* row_in = input + (long long)row * cols;
    float* row_out = output + (long long)row * cols;

    // Each thread accumulates elements it owns (strided by BLOCK_SCAN_THREADS)
    // We need sequential prefix, so we do a two-pass approach:
    // Pass 1: each thread computes its local sum over its chunk
    // Then block-level scan of per-thread totals
    // Pass 2: each thread adds its prefix and writes outputs

    // Compute per-thread total (sequential scan within thread's elements)
    float local_sum = 0.0f;
    for (int i = tid; i < cols; i += BLOCK_SCAN_THREADS) {
        local_sum += row_in[i];
    }

    // Warp-level inclusive scan of local_sum
    float warp_scan = warp_inclusive_scan(local_sum);

    // Store warp totals to shared memory
    if (lane == 31 || (warp_id * 32 + 31) >= BLOCK_SCAN_THREADS - 1) {
        // last lane in warp stores warp total
        smem[warp_id] = warp_scan;
    }
    __syncthreads();

    // Scan warp totals in thread 0..num_warps-1
